const targetMap = new WeakMap();
let activeEffect = null;
const effectStack = [];
function isObject(v){return v!==null && typeof v==="object";}
function track(target,key){
  if(!activeEffect) return;
  let dm=targetMap.get(target);
  if(!dm){targetMap.set(target,(dm=new Map()));}
  let dep=dm.get(key);
  if(!dep){dm.set(key,(dep=new Set()));}
  dep.add(activeEffect);
  activeEffect.deps.add(dep);
}
function trigger(target,key){
  const dm=targetMap.get(target);
  if(!dm) return;
  const dep=dm.get(key);
  if(!dep) return;
  [...dep].forEach(e=>e.run());
}
const ARRAY_METHODS = ["push","pop","shift","unshift","splice","sort","reverse"];
function reactive(obj){
  if(!isObject(obj)) return obj;
  return new Proxy(obj,{
    get(t,k,r){
      const res=Reflect.get(t,k,r);
      if(Array.isArray(t) && ARRAY_METHODS.includes(k)){
        return function(...args){
          const result = res.apply(t, args);
          trigger(t, "length");
          return result;
        };
      }
      track(t,k);
      if(isObject(res)) return reactive(res);
      return res;
    },
    set(t,k,v,r){ const old=t[k]; const res=Reflect.set(t,k,v,r); if(old!==v){ trigger(t,k); trigger(t,"length"); } return res; }
  });
}
function ref(raw){
  const r={ _value:raw,
    get value(){ track(r,"value"); return this._value; },
    set value(v){ this._value=v; trigger(r,"value"); } };
  return r;
}
function effect(fn){
  const e={ deps:new Set(), run(){
    cleanup(e); effectStack.push(e); activeEffect=e;
    try{ return fn(); } finally { effectStack.pop(); activeEffect=effectStack[effectStack.length-1]||null; }
  }};
  function cleanup(eff){ eff.deps.forEach(d=>d.delete(eff)); eff.deps.clear(); }
  e.run();
  return e;
}
function toRefs(state){
  const ret={};
  for(const k of Object.keys(state)){
    ret[k]={ get value(){ return state[k]; }, set value(v){ state[k]=v; } };
  }
  return ret;
}
function computed(getter){
  let value;
  effect(()=>{ value=getter(); });
  return { get value(){ return value; } };
}

